using Rea.Notebook;
using System.Text;
using System.Text.Json;
var workspace=Path.GetFullPath(args[0]);
var results=new List<object>();int failures=0;
async Task Check(string name,Func<Task> action){try{await action();results.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception e){failures++;results.Add(new{name,passed=false,error=e.Message});Console.WriteLine("FAIL "+name+": "+e.Message);}}
void Assert(bool x,string m="Assertion failed"){if(!x)throw new Exception(m);}
void Refuses(Action action){try{action();}catch(Exception e)when(e is InvalidDataException or JsonException or IOException or FormatException or UnauthorizedAccessException){return;}throw new Exception("Expected refusal");}
async Task RefusesAsync(Func<Task> action){try{await action();}catch(Exception e)when(e is InvalidDataException or IOException or OperationCanceledException){return;}throw new Exception("Expected refusal");}
(string input,string output) Files(){var folder="test-owned/"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(Notebook.Resolve(workspace,folder));var input=folder+"/input.json";File.WriteAllText(Notebook.Resolve(workspace,input),"{\"Values\":[3,6,9]}");return(input,folder+"/output.json");}
CommandPlan Compute((string input,string output) f,int factor=2,int timeout=5000)=>Notebook.Create(workspace,"NotebookFixture.exe",new[]{"compute",f.input,f.output},new[]{f.input},new[]{f.output},new(){{"REA_FACTOR",factor.ToString()}},timeout);
CommandPlan Mode(string mode,int timeout=5000)=>Notebook.Create(workspace,"NotebookFixture.exe",new[]{mode},Array.Empty<string>(),Array.Empty<string>(),new(),timeout);
ReceiptEnvelope Reseal(ExecutionReceipt r)=>new(r,Notebook.CanonicalDigest(r));
await Check("Native process produces captured file and exact stdout bytes",async()=>{var f=Files();var p=Compute(f);var r=await Notebook.Run(workspace,p);Assert(r.Receipt.Outcome=="completed");Assert(r.Receipt.Stdout.Text.Contains("[6,12,18]"));Assert(r.Receipt.OutputsAfter[f.output]==Notebook.FileHash(Notebook.Resolve(workspace,f.output)));Notebook.VerifyReceipt(r,p);});
await Check("Same sealed plan reruns against unchanged declared input",async()=>{var p=Compute(Files());var a=await Notebook.Run(workspace,p);Assert(Notebook.Preview(workspace,p).Ready);var b=await Notebook.Run(workspace,p);Assert(a.Receipt.OutputsAfter.SequenceEqual(b.Receipt.OutputsAfter));Assert(a.Receipt.Stdout.Sha256==b.Receipt.Stdout.Sha256);});
await Check("One-factor environment change yields different committed output",async()=>{var f=Files();var a=await Notebook.Run(workspace,Compute(f,2));var b=await Notebook.Run(workspace,Compute(f,3));Assert(a.Receipt.Stdout.Sha256!=b.Receipt.Stdout.Sha256);Assert(b.Receipt.Stdout.Text.Contains("[9,18,27]"));});
await Check("Changed input refuses before execution",async()=>{var f=Files();var p=Compute(f);File.AppendAllText(Notebook.Resolve(workspace,f.input)," ");Assert(!Notebook.Preview(workspace,p).Ready);await RefusesAsync(async()=>{await Notebook.Run(workspace,p);});Assert(!File.Exists(Notebook.Resolve(workspace,f.output)));});
await Check("Changed executable refuses before launch",async()=>{var f=Files();var copy="test-owned/altered.exe";File.Copy(Notebook.Resolve(workspace,"NotebookFixture.exe"),Notebook.Resolve(workspace,copy),true);var p=Notebook.Create(workspace,copy,[],[f.input],[f.output],new(),5000);File.AppendAllText(Notebook.Resolve(workspace,copy),"x");Assert(!Notebook.Preview(workspace,p).Ready);await RefusesAsync(async()=>{await Notebook.Run(workspace,p);});});
await Check("Tampered plan fails sealed digest",()=>{var p=Compute(Files());Refuses(()=>Notebook.VerifyPlan(p with {Spec=p.Spec with {TimeoutMs=1234}}));return Task.CompletedTask;});
await Check("Unsupported schema refused even with recomputed digest",()=>{var p=Compute(Files());var s=p.Spec with {Schema=2};Refuses(()=>Notebook.VerifyPlan(new(s,Notebook.CanonicalDigest(s))));return Task.CompletedTask;});
await Check("Duplicate JSON properties refused",()=>{Refuses(()=>Notebook.Parse<CommandPlan>(Encoding.UTF8.GetBytes("{\"Spec\":null,\"Spec\":null,\"Sha256\":\"x\"}")));return Task.CompletedTask;});
await Check("Unknown JSON properties refused",()=>{Refuses(()=>Notebook.Parse<PreviewResult>(Encoding.UTF8.GetBytes("{\"Ready\":true,\"Reasons\":[],\"RunImmediately\":true}")));return Task.CompletedTask;});
await Check("Oversized JSON refused",()=>{Refuses(()=>Notebook.Parse<PreviewResult>(new byte[2*Notebook.FileLimit+1]));return Task.CompletedTask;});
await Check("Traversal absolute drive ADS and backslash paths refused",()=>{foreach(var x in new[]{"../a","/a","C:/a","a:b","a\\b","a//b","a/./b"})Refuses(()=>Notebook.Relative(x));return Task.CompletedTask;});
await Check("Windows aliases and trailing dot/space paths refused",()=>{foreach(var x in new[]{"CON","aux.txt","x/LPT1.txt","foo.","foo ","a?b"})Refuses(()=>Notebook.Relative(x));return Task.CompletedTask;});
await Check("Input output casing collision refused",()=>{var p=Compute(Files());Refuses(()=>Notebook.Validate(p.Spec with {Outputs=new[]{p.Spec.Inputs.Keys.First().ToUpperInvariant()}}));return Task.CompletedTask;});
await Check("Ancestor output collision refused",()=>{var p=Compute(Files());Refuses(()=>Notebook.Validate(p.Spec with {Outputs=new[]{p.Spec.Inputs.Keys.First()+"/file"}}));return Task.CompletedTask;});
await Check("Notebook internal paths reserved",()=>{var p=Compute(Files());Refuses(()=>Notebook.Validate(p.Spec with {Outputs=new[]{".rea-notebook/run.lock"}}));return Task.CompletedTask;});
await Check("Secret-shaped and ambient environment overrides refused",()=>{foreach(var key in new[]{"PATH","HOME","REA_API_KEY","REA_TOKEN","REA_PASSWORD"}){var p=Compute(Files());Refuses(()=>Notebook.Validate(p.Spec with {Environment=new(){{key,"x"}}}));}return Task.CompletedTask;});
await Check("Argument vector preserves shell metacharacters literally",async()=>{var text="a & echo INJECTED > x; $(whoami)";var p=Notebook.Create(workspace,"NotebookFixture.exe",new[]{"echo",text},[],[],new(),5000);var r=await Notebook.Run(workspace,p);Assert(JsonSerializer.Deserialize<string[]>(r.Receipt.Stdout.Text)![0]==text);Assert(!File.Exists(Notebook.Resolve(workspace,"x")));});
await Check("Nonzero process exit stays failed",async()=>{var p=Mode("fail");var r=await Notebook.Run(workspace,p);Assert(r.Receipt.Outcome=="failed"&&r.Receipt.ExitCode==7);Assert(r.Receipt.Stderr.Text.Contains("fixture failure"));Notebook.VerifyReceipt(r,p);});
await Check("Timeout kills owned process and does not claim completion",async()=>{var p=Mode("sleep",150);var r=await Notebook.Run(workspace,p);Assert(r.Receipt.Outcome=="timed-out"&&r.Receipt.ParentExitConfirmed);Notebook.VerifyReceipt(r,p);});
await Check("Explicit running cancellation records interruption",async()=>{var p=Mode("sleep");using var c=new CancellationTokenSource(150);var r=await Notebook.Run(workspace,p,c.Token);Assert(r.Receipt.Outcome=="interrupted"&&r.Receipt.ParentExitConfirmed);});
await Check("Pre-cancelled run never launches",async()=>{using var c=new CancellationTokenSource();c.Cancel();await RefusesAsync(async()=>{await Notebook.Run(workspace,Mode("sleep"),c.Token);});});
await Check("Bounded stdout captures partial bytes and refuses completion",async()=>{var p=Mode("flood");var r=await Notebook.Run(workspace,p);Assert(r.Receipt.Outcome=="output-limit");Assert(r.Receipt.Stdout.Truncated&&r.Receipt.Stdout.Bytes==Notebook.StreamLimit);Notebook.VerifyReceipt(r,p);});
await Check("Child receives sealed environment without inherited secret",async()=>{Environment.SetEnvironmentVariable("RESEARCH_SECRET","test-only-secret");try{var p=Notebook.Create(workspace,"NotebookFixture.exe",new[]{"env"},[],[],new(){{"REA_FACTOR","3"}},5000);var r=await Notebook.Run(workspace,p);using var j=JsonDocument.Parse(r.Receipt.Stdout.Text);Assert(j.RootElement.GetProperty("secret").ValueKind==JsonValueKind.Null);Assert(j.RootElement.GetProperty("factor").GetString()=="3");Assert(j.RootElement.GetProperty("path").GetString()=="");Assert(j.RootElement.GetProperty("profileInside").GetBoolean());}finally{Environment.SetEnvironmentVariable("RESEARCH_SECRET",null);}});
await Check("Declared input mutated by child invalidates completion",async()=>{var f=Files();var p=Notebook.Create(workspace,"NotebookFixture.exe",new[]{"mutate",f.input},[f.input],[],new(),5000);var r=await Notebook.Run(workspace,p);Assert(r.Receipt.Outcome=="input-changed");Notebook.VerifyReceipt(r,p);});
await Check("Output directory rejected at preview",()=>{var f=Files();Directory.CreateDirectory(Notebook.Resolve(workspace,f.output));var p=Compute(f);Assert(!Notebook.Preview(workspace,p).Ready);return Task.CompletedTask;});
await Check("Oversized declared input rejected",()=>{var f=Files();File.WriteAllBytes(Notebook.Resolve(workspace,f.input),new byte[Notebook.FileLimit+1]);Refuses(()=>Compute(f));return Task.CompletedTask;});
await Check("Concurrent workspace execution lock refuses second process",async()=>{var p=Mode("sleep",500);var first=Notebook.Run(workspace,p);await Task.Delay(75);await RefusesAsync(async()=>{await Notebook.Run(workspace,Mode("echo"));});await first;});
await Check("Receipt tampering detected",async()=>{var p=Compute(Files());var r=await Notebook.Run(workspace,p);Refuses(()=>Notebook.VerifyReceipt(r with {Receipt=r.Receipt with {Outcome="failed"}},p));});
await Check("Resealed inconsistent output commitment rejected",async()=>{var p=Compute(Files());var r=await Notebook.Run(workspace,p);var bad=Reseal(r.Receipt with {Stdout=r.Receipt.Stdout with {Sha256=new string('0',64)}});Refuses(()=>Notebook.VerifyReceipt(bad,p));});
await Check("Resealed false completion with failure exit rejected",async()=>{var p=Mode("fail");var r=await Notebook.Run(workspace,p);Refuses(()=>Notebook.VerifyReceipt(Reseal(r.Receipt with {Outcome="completed"}),p));});
await Check("Independent anchor detects fully resealed edit",async()=>{var p=Mode("echo");var r=await Notebook.Run(workspace,p);var changed=Reseal(r.Receipt with {DurationMs=r.Receipt.DurationMs+1});Refuses(()=>Notebook.VerifyReceipt(changed,p,r.Sha256));});
await Check("Atomic create-new save never overwrites evidence",()=>{var f=Files();var path=Notebook.Resolve(workspace,f.output);Notebook.SaveNew(path,new{Value=1});Refuses(()=>Notebook.SaveNew(path,new{Value=2}));Assert(File.ReadAllText(path).Contains("1"));return Task.CompletedTask;});
await Check("Unicode input identity survives strict plan serialization",async()=>{var f=Files();var folder=f.input[..f.input.LastIndexOf('/')];var unicode=folder+"/Ä.txt";File.WriteAllText(Notebook.Resolve(workspace,unicode),"owned input");var p=Notebook.Create(workspace,"NotebookFixture.exe",new[]{"echo","unicode"},new[]{f.input,unicode},[],new(),5000);var clone=Notebook.Parse<CommandPlan>(JsonSerializer.SerializeToUtf8Bytes(p,Notebook.Json));var r=await Notebook.Run(workspace,clone);Assert(r.Receipt.Outcome=="completed");Notebook.VerifyReceipt(r,clone);});
await Check("Malformed Unicode path and aggregate argv size refused",()=>{Refuses(()=>Notebook.Relative("bad\uD800"));var p=Compute(Files());Refuses(()=>Notebook.Validate(p.Spec with {Arguments=Enumerable.Repeat(new string('a',1000),20).ToArray()}));return Task.CompletedTask;});
await Check("Plan object edits after launch do not change captured execution",async()=>{var p=Mode("sleep",150);var task=Notebook.Run(workspace,p);p.Spec.Arguments[0]="fail";var r=await task;Assert(r.Receipt.Outcome=="timed-out");});
var sourceRoot=Path.GetDirectoryName(Path.GetDirectoryName(Path.GetFullPath(args[1])))!;
var testedFiles=new SortedDictionary<string,string>(StringComparer.Ordinal);
foreach(var name in new[]{"src/Core/Notebook.cs","src/Core/Notebook.Core.csproj","tests/Tests.cs","tests/Notebook.Tests.csproj","tests/Fixture.cs","tests/Fixture.csproj","Directory.Build.props","global.json","NuGet.Config"})testedFiles[name]=Notebook.FileHash(Path.Combine(sourceRoot,name));
var fixtureFiles=new SortedDictionary<string,string>(StringComparer.Ordinal);
foreach(var name in new[]{"NotebookFixture.exe","NotebookFixture.dll"})fixtureFiles[name]=Notebook.FileHash(Notebook.Resolve(workspace,name));
var report=new{tested_source_files=testedFiles,tested_fixture_files=fixtureFiles,passed=results.Count-failures,total=results.Count,checks=results,nativeProcessesExecuted=true,scope="Synthetic owned fixture. No installed Warp, PTY, cloud, SSH or remote commands."};
File.WriteAllText(args[1],JsonSerializer.Serialize(report,Notebook.Json));
return failures==0?0:1;
